        stripped = line.strip()
        heading = re.match(r'^(#{2,4})\s*(\d+(?:\.\d+)*)', stripped)
        if heading:
            section = heading.group(2)
            continue
        if not stripped.startswith('|'):
            continue
        cells = [c.strip() for c in stripped.strip('|').split('|')]
        if len(cells) < 4 or set(cells[0]) <= set('-: '):
            continue
        head = cells[0].strip('`')
        if not re.match(r'^[A-Za-z0-9+]{2,6}$', head):
